-- Update: jimmy-butler weight_bearing 2026-11-07
INSERT INTO progress_updates (injury_id, update_date, stage, status_label, notes, source)
SELECT i.id, '2026-11-07', 'weight_bearing', 'Worked out in full uniform; no return date', 'Steve Kerr said before Saturday''s Nov. 7 game that Butler worked out in his full Warriors uniform (via ClutchPoints'' Kenzo Fukuda). Still listed out on the NBA injury report; the team has not set a return date.', 'https://www.hoopsrumors.com/2026/11/warriors-notes-porzingis-butler-curry-lendeborg-defense.html'
FROM injuries i JOIN players p ON p.id = i.player_id
WHERE p.slug = 'jimmy-butler' AND p.league = 'NBA' AND i.injury_type = 'ACL' AND i.injury_date = '2026-01-19'
  AND NOT EXISTS (SELECT 1 FROM progress_updates x WHERE x.injury_id = i.id AND x.stage = 'weight_bearing' AND x.update_date = '2026-11-07');

